def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings."""
    # Simple approach: find first difference and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first position where they differ
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(s_in) < len(s_out):
            return (s_in[-1] if s_in else "", s_out[len(s_in):], len(s_in)-1 if s_in else 0)
        elif len(s_in) > len(s_out):
            return (s_in[len(s_out):], "", len(s_out))
        else:
            return ("", "", -1)

    # Find what's being replaced/added/removed
    old_sub = ""
    new_sub = ""

    # Check if it's insertion (length increase)
    if len(s_in) < len(s_out):
        # Insertion at pos
        old_sub = ""
        new_sub = s_out[pos:pos+1]
    elif len(s_in) > len(s_out):
        # Deletion at pos  
        old_sub = s_in[pos:pos+1]
        new_sub = ""
    else:
        # Substitution
        old_sub = s_in[pos:pos+1]
        new_sub = s_out[pos:pos+1]

    return (old_sub, new_sub, pos)

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates from a change."""
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # Return the basic rule and variations
    candidates = []

    # Most specific: exact match
    if old_sub:
        candidates.append((old_sub, new_sub))

    # Generalize to patterns
    if len(old_sub) == 1 and len(new_sub) == 1:
        candidates.append((old_sub, new_sub))

    # If there's a pattern that could be extended, we might want to consider it
    # But for now, let's focus on the direct substitution
    return candidates

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings."""
    result = []
    for s in strings:
        new_s = s
        for pattern, replacement in rules:
            new_s = new_s.replace(pattern, replacement)
        result.append(new_s)
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules match the expected outputs."""
    results = apply_rules(inputs, rules)
    correct = sum(1 for i, r in enumerate(results) if r == outputs[i])
    return correct / len(outputs) if outputs else 0

